func (this *Polymarket) fetchStatusBody(ch chan AsyncResult[Status], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetInfoExchange(params)
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	//     {
	//         "name": "Polymarket",
	//         "version": "1",
	//         "chain_id": 137,
	//         "contract": "0xDCa4af75705dbB50f62437045afF9921947917d2",
	//         "cancel_only": false,
	//         "engine_version": "0.0.69"
	//     }
	//
	var cancelOnly *bool = this.SafeBool(response, "cancel_only", false)

	ch <- AsyncResult[Status]{Value: StatusFromMap(map[string]any{
		"status": func() string {
			if cancelOnly != nil && *cancelOnly {
				return "maintenance"
			}
			return "ok"
		}(),
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	})}
	return nil
}

/**
 * @method
 * @name polymarket#fetchCurrencies
 * @description fetches all available currencies on an exchange - every instrument base, the usd quote and the collateral asset
 * @see https://docs.polymarket.com/perps/market-data
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Polymarket) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var promises []any = []any{this.PublicGetInfoInstruments(params), this.PublicGetInfoAssets(params)}

	r := <-promiseAll(promises)
	if r.Err != nil {
		panic(r.Err)
	}
	var responses []any = ListTyped(r.Value)
	var instruments []any = SafeListTyped(responses, 0)
	var assets []any = SafeListTyped(responses, 1)
	var result map[string]any = map[string]any{}
	for i := 0; i < len(instruments); i++ {
		var instrument any = instruments[i]
		var baseId *string = this.SafeString(instrument, "base_asset")
		if baseId == nil {
			continue
		}
		var code *string = this.SafeCurrencyCode(baseId)
		if !(InOp(result, code)) {
			// the venue tags each underlying with a category - only the
			// crypto ones are unified as crypto, equities, commodities and
			// indices map onto the other currency type
			var category *string = this.SafeString(instrument, "category")
			var currencyType string = func() string {
				if category != nil && *category == "crypto" {
					return "crypto"
				}
				return "other"
			}()
			AddElementToObject(result, code, this.SafeCurrencyStructure(map[string]any{
				"id":        baseId,
				"code":      code,
				"name":      baseId,
				"info":      instrument,
				"active":    true,
				"deposit":   false,
				"withdraw":  false,
				"fee":       nil,
				"precision": this.ParseNumber(this.ParsePrecision(this.SafeString(instrument, "quantity_decimals"))),
				"type":      currencyType,
				"networks":  map[string]any{},
			}))
		}
	}
	// every instrument quotes using usd
	result["USD"] = this.SafeCurrencyStructure(map[string]any{
		"id":        "USD",
		"code":      "USD",
		"name":      "USD",
		"info":      map[string]any{},
		"active":    true,
		"deposit":   false,
		"withdraw":  false,
		"fee":       nil,
		"precision": this.ParseNumber("0.01"),
		"type":      "fiat",
		"networks":  map[string]any{},
	})
	for i := 0; i < len(assets); i++ {
		var asset any = assets[i]
		var currencyId *string = this.SafeString(asset, "asset")
		if currencyId == nil {
			continue
		}
		var code *string = this.SafeCurrencyCode(currencyId)
		AddElementToObject(result, code, this.SafeCurrencyStructure(map[string]any{
			"id":        currencyId,
			"code":      code,
			"name":      currencyId,
			"info":      asset,
			"active":    true,
			"deposit":   true,
			"withdraw":  true,
			"fee":       this.SafeNumber(asset, "withdrawal_fee"),
			"precision": this.ParseNumber(this.ParsePrecision(this.SafeString(asset, "decimals"))),
			"type":      "crypto",
			"networks":  map[string]any{},
		}))
	}

	ch <- AsyncResult[map[string]any]{Value: result}
	return nil
}

