/**
 * @method
 * @name polymarket#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market, merging the ticker, statistics and best bid and ask endpoints
 * @see https://docs.polymarket.com/perps/market-data
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/#/?id=ticker-structure}
 */
func (this *Polymarket) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = this.Market(symbol)
	var symbolResolved *string = SafeStringPtr(market["symbol"])
	// the tickers and statistics endpoints ignore the documented
	// instrument_id filter and always answer with every instrument, so
	// the single-market call reuses the bulk fetch and selects one row

	r1 := <-this.FetchTickersAsync([]any{symbolResolved}, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var tickers map[string]any = StructResultMap(r1.Value, TickerMapToMap)
	var ticker map[string]any = SafeMapTyped(tickers, symbolResolved)
	if ticker == nil {
		panic(BadSymbol(this.Id + " fetchTicker() could not find a ticker for " + *symbolResolved))
	}

	ch <- AsyncResult[Ticker]{Value: TickerFromMap(ticker)}
	return nil
}

/**
 * @method
 * @name polymarket#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market, merging the ticker, statistics and best bid and ask endpoints
 * @see https://docs.polymarket.com/perps/market-data
 * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/#/?id=ticker-structure}
 */
func (this *Polymarket) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var promises []any = []any{this.PublicGetInfoTickers(params), this.PublicGetInfoStatistics(params), this.PublicGetInfoBbo(params)}

	r1 := <-promiseAll(promises)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var responses []any = ListTyped(r1.Value)
	//
	// tickers
	//
	//     [
	//         {
	//             "instrument_id": 1,
	//             "symbol": "SP500-USD",
	//             "index_price": "7713.1",
	//             "mark_price": "7715",
	//             "last_price": "7714",
	//             "mid_price": "7715",
	//             "open_interest": "1101.82729",
	//             "funding_rate": "0.00000625",
	//             "next_funding": 1788548400000,
	//             "timestamp": 1788546972857
	//         }
	//     ]
	//
	// statistics
	//
	//     [
	//         {
	//             "instrument_id": 1,
	//             "symbol": "SP500-USD",
	//             "volume": "2087643.9565559996",
	//             "open_price": "7754.5",
	//             "klines": [ [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ] ]
	//         }
	//     ]
	//
	// bbo
	//
	//     [
	//         {
	//             "instrument_id": 1,
	//             "bid_price": "7715",
	//             "bid_quantity": "22.63803",
	//             "ask_price": "7715.1",
	//             "ask_quantity": "0.95534",
	//             "timestamp": 1788546975038
	//         }
	//     ]
	//
	var merged map[string]any = map[string]any{}
	var statistics []any = SafeListTyped(responses, 1)
	for i := 0; i < len(statistics); i++ {
		var entry any = statistics[i]
		var instrumentId *string = this.SafeString(entry, "instrument_id")
		// the 24 hourly kline rows are dropped from the merged payload to keep tickers light, candles are served by fetchOHLCV
		AddElementToObject(merged, instrumentId, this.Omit(entry, "klines"))
	}
	var bbos []any = SafeListTyped(responses, 2)
	for i := 0; i < len(bbos); i++ {
		var entry any = bbos[i]
		var instrumentId *string = this.SafeString(entry, "instrument_id")
		var previous map[string]any = this.SafeDictMap(merged, instrumentId, map[string]any{})
		// the tickers endpoint timestamp wins the merge below because most unified fields come from it - bbo rows carry a slightly newer sampling time
		if instrumentId != nil {
			merged[*instrumentId] = this.Extend(previous, entry)
		}
	}
	var tickers []any = SafeListTyped(responses, 0)
	var result []any = []any{}
	for i := 0; i < len(tickers); i++ {
		var entry any = tickers[i]
		var instrumentId *string = this.SafeString(entry, "instrument_id")
		var previous map[string]any = this.SafeDictMap(merged, instrumentId, map[string]any{})
		result = append(result, this.Extend(previous, entry))
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.ParseTickers(result, symbolsNormalized))}
	return nil
}
func (this *Polymarket) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// merged row assembled by fetchTickers from the tickers, statistics and bbo endpoints
	//
	//     {
	//         "instrument_id": 1,
	//         "symbol": "SP500-USD",
	//         "volume": "2087643.9565559996",
	//         "open_price": "7754.5",
	//         "bid_price": "7715",
	//         "bid_quantity": "22.63803",
	//         "ask_price": "7715.1",
	//         "ask_quantity": "0.95534",
	//         "index_price": "7713.1",
	//         "mark_price": "7715",
	//         "last_price": "7714",
	//         "mid_price": "7715",
	//         "open_interest": "1101.82729",
	//         "funding_rate": "0.00000625",
	//         "next_funding": 1788548400000,
	//         "timestamp": 1788546972857
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "instrument_id")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(ticker, "timestamp")
	return this.SafeTicker(map[string]any{
		"symbol":        marketResolved["symbol"],
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          nil,
		"low":           nil,
		"bid":           this.SafeString(ticker, "bid_price"),
		"bidVolume":     this.SafeString(ticker, "bid_quantity"),
		"ask":           this.SafeString(ticker, "ask_price"),
		"askVolume":     this.SafeString(ticker, "ask_quantity"),
		"vwap":          nil,
		"open":          this.SafeString(ticker, "open_price"),
		"close":         this.SafeString(ticker, "last_price"),
		"last":          this.SafeString(ticker, "last_price"),
		"previousClose": nil,
		"change":        nil,
		"percentage":    nil,
		"average":       nil,
		"baseVolume":    nil,
		"quoteVolume":   this.SafeString(ticker, "volume"),
		"markPrice":     this.SafeString(ticker, "mark_price"),
		"indexPrice":    this.SafeString(ticker, "index_price"),
		"info":          ticker,
	}, marketResolved)
}

