/**
 * @method
 * @name polymarket#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.polymarket.com/perps/market-data
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of funding rate structures to fetch, the venue serves at most 100 per request
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest funding rate to fetch
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling the endpoint multiple times
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/#/?id=funding-rate-history-structure}
 */
func (this *Polymarket) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a symbol argument"))
	}

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var paginate bool = false
	var paramsOmitted any = params
	var paginateparamsOmittedVariable []any = this.HandleOptionAndParams(paramsOmitted, "fetchFundingRateHistory", "paginate")
	paginate = GetValueBool(paginateparamsOmittedVariable, 0, false)
	paramsOmitted = paginateparamsOmittedVariable[1]
	if paginate {

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchFundingRateHistory", symbol, since, limit, "1h", paramsOmitted, 100)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes109619 []any = r1.Value
		if retRes109619 == nil {
			ch <- AsyncResult[[]FundingRateHistory]{Value: nil}
		} else {
			ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(retRes109619)}
		}
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"instrument_id": market["id"],
	}
	if since != nil {
		request["start_timestamp"] = since
	}
	var until *int64 = this.SafeInteger(paramsOmitted, "until")
	if until != nil {
		paramsOmitted = this.Omit(paramsOmitted, "until")
		request["end_timestamp"] = until
	}

	r2 := <-this.PublicGetInfoFunding(this.Extend(request, paramsOmitted))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//     {
	//         "data": [
	//             { "funding_rate": "0.00000625", "timestamp": 1788544800063 }
	//         ],
	//         "more": false
	//     }
	//
	var data []any = SafeListTyped(response, "data")
	var rates []any = []any{}
	for i := 0; i < len(data); i++ {
		var entry any = DerefScalar(data[i])
		var timestamp *int64 = this.SafeInteger(entry, "timestamp")
		rates = append(rates, map[string]any{
			"info":        entry,
			"symbol":      market["symbol"],
			"fundingRate": this.SafeNumber(entry, "funding_rate"),
			"timestamp":   timestamp,
			"datetime":    this.Iso8601(timestamp),
		})
	}
	var sorted []any = this.SortBy(rates, "timestamp")

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.FilterBySymbolSinceLimit(sorted, market["symbol"], since, limit))}
	return nil
}

