func (this *Polymarket) cancelOrdersBody(ch chan AsyncResult[[]Order], ids any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var clientOrderIds any = this.SafeList2(params, "clientOrderIds", "clientOrderId")
	if clientOrderIds == nil {
		var clientOrderId *string = this.SafeString(params, "clientOrderId")
		if clientOrderId != nil {
			clientOrderIds = []any{clientOrderId}
		}
	}
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"clientOrderIds", "clientOrderId"})
	var signable []any = nil
	var bodyOp map[string]any = nil
	var response []any = nil
	if clientOrderIds != nil {
		signable = []any{"cancelOrdersCOID", clientOrderIds}
		bodyOp = map[string]any{
			"type": "cancelOrdersCOID",
			"args": clientOrderIds,
		}

		r1 := <-this.SignPerpsOpAsync(signable, bodyOp, paramsOmitted)
		if r1.Err != nil {
			panic(r1.Err)
		}
		signed := r1.Value

		listEp1935 := <-this.TradeDeleteTradeOrdersCoid(signed)
		if listEp1935.Err != nil {
			panic(listEp1935.Err)
		}
		response = listEp1935.Value
	} else {
		var numericIds []any = []any{}
		for i := 0; i < GetArrayLength(ids); i++ {
			numericIds = append(numericIds, this.ParseToInt(this.SafeString(ids, i)))
		}
		signable = []any{"cancelOrders", numericIds}
		bodyOp = map[string]any{
			"type": "cancelOrders",
			"args": numericIds,
		}

		r2 := <-this.SignPerpsOpAsync(signable, bodyOp, paramsOmitted)
		if r2.Err != nil {
			panic(r2.Err)
		}
		signed := r2.Value

		listEp1950 := <-this.TradeDeleteTradeOrders(signed)
		if listEp1950.Err != nil {
			panic(listEp1950.Err)
		}
		response = listEp1950.Value
	}
	//
	//     [
	//         { "status": "ok", "oid": 1234567890, "ts": 1788546565789 }
	//     ]
	//
	var results []any = []any{}
	for i := 0; i < len(response); i++ {
		var ack map[string]any = this.SafeDictMap(response, i, map[string]any{})
		var status *string = this.SafeString(ack, "status")
		var unified string = func() string {
			if status != nil && *status == "err" {
				return "rejected"
			}
			return "canceled"
		}()
		var merged map[string]any = map[string]any{
			"oid":    this.SafeInteger(ack, "oid"),
			"coid":   this.SafeString(ack, "coid"),
			"uts":    this.SafeInteger(ack, "ts"),
			"status": unified,
		}
		var parsed map[string]any = OrderToMap(this.ParseOrder(merged))
		parsed["info"] = ack
		results = append(results, parsed)
	}

	ch <- AsyncResult[[]Order]{Value: OrdersFromList(results)}
	return nil
}

