func (this *Polymarket) fetchPositionsBody(ch chan AsyncResult[[]Position], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}

	r1 := <-this.LoadProxyCredentialsAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)

	r2 := <-this.PrivateGetAccountPortfolio(params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	var timestamp *int64 = this.SafeInteger(response, "timestamp")
	var rows []any = SafeListTyped(response, "positions")
	var positions []any = []any{}
	for i := 0; i < len(rows); i++ {
		// the wrapper timestamp flows into the parser through the merged input
		var extended map[string]any = this.Extend(rows[i], map[string]any{
			"timestamp": timestamp,
		})
		positions = append(positions, PositionToMap(this.ParsePosition(extended)))
	}

	ch <- AsyncResult[[]Position]{Value: PositionsFromList(this.FilterByArrayPositions(positions, "symbol", symbolsNormalized))}
	return nil
}

