func (this *Polymarket) ParsePosition(position any, optionalArgs ...any) Position {
	//
	//     {
	//         "instrument_id": 6,
	//         "symbol": "BTC-USD",
	//         "size": "-0.001",
	//         "entry_price": "79650.0",
	//         "leverage": 10,
	//         "cross": true,
	//         "initial_margin": "7.97",
	//         "maintenance_margin": "3.99",
	//         "position_value": "79.65",
	//         "liquidation_price": "85000.0",
	//         "unrealized_pnl": "-0.10",
	//         "return_on_equity": "-0.0125",
	//         "cumulative_funding": "0.01",
	//         "timestamp": 1788546565789
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "instrument_id")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var size *string = this.SafeString(position, "size")
	var side *string = nil
	if size != nil {
		var isLong bool = Precise.StringGt(size, "0")
		side = SafeStringPtr(func() string {
			if isLong {
				return "long"
			}
			return "short"
		}())
	}
	var isCross *bool = this.SafeBool(position, "cross")
	var marginMode *string = nil
	if isCross != nil {
		marginMode = SafeStringPtr(func() string {
			if isCross != nil && *isCross {
				return "cross"
			}
			return "isolated"
		}())
	}
	var timestamp *int64 = this.SafeInteger(position, "timestamp")
	var roe *string = this.SafeString(position, "return_on_equity")
	var percentage *float64 = nil
	if roe != nil {
		percentage = this.ParseNumber(Precise.StringMul(roe, "100"))
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      marketResolved["symbol"],
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"lastUpdateTimestamp":         nil,
		"initialMargin":               this.SafeNumber(position, "initial_margin"),
		"initialMarginPercentage":     nil,
		"maintenanceMargin":           this.SafeNumber(position, "maintenance_margin"),
		"maintenanceMarginPercentage": nil,
		"entryPrice":                  this.SafeNumber(position, "entry_price"),
		"notional":                    this.SafeNumber(position, "position_value"),
		"leverage":                    this.SafeInteger(position, "leverage"),
		"unrealizedPnl":               this.SafeNumber(position, "unrealized_pnl"),
		"realizedPnl":                 nil,
		"contracts":                   this.ParseNumber(Precise.StringAbs(size)),
		"contractSize":                marketResolved["contractSize"],
		"marginRatio":                 nil,
		"liquidationPrice":            this.ParseNumber(this.OmitZero(this.SafeString(position, "liquidation_price"))),
		"markPrice":                   nil,
		"lastPrice":                   nil,
		"collateral":                  this.SafeNumber(position, "initial_margin"),
		"marginMode":                  marginMode,
		"side":                        side,
		"percentage":                  percentage,
		"hedged":                      false,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
	})
}

