func (this *Polymarket) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"pending":   "pending",
		"confirmed": "ok",
		"removed":   "failed",
		"failed":    "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Polymarket) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// deposit row
	//
	//     {
	//         "hash": "0x...",
	//         "asset": "USDC",
	//         "amount": "100",
	//         "from": "0x...",
	//         "to": "0x...",
	//         "status": "confirmed",
	//         "confirmations": 10,
	//         "required_confirmations": 10,
	//         "created_timestamp": 1788546565789,
	//         "confirmed_timestamp": 1788546570789
	//     }
	//
	// withdrawal row
	//
	//     {
	//         "withdraw_id": 123,
	//         "asset": "USDC",
	//         "amount": "100",
	//         "to": "0x...",
	//         "fee": "0.1",
	//         "status": "pending",
	//         "hash": "0x",
	//         "confirmations": 0,
	//         "required_confirmations": 10,
	//         "created_timestamp": 1788546565789
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var withdrawId *string = this.SafeString(transaction, "withdraw_id")
	var typeVar string = func() string {
		if withdrawId != nil {
			return "withdrawal"
		}
		return "deposit"
	}()
	var currencyId *string = this.SafeString(transaction, "asset")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = this.SafeInteger(transaction, "created_timestamp")
	var rawHash *string = this.SafeString(transaction, "hash")
	// the venue reports the literal 0x prefix while the transaction is unmined
	var txid *string = func() *string {
		if rawHash != nil && *rawHash == "0x" {
			return nil
		}
		return rawHash
	}()
	var feeCost *string = this.SafeString(transaction, "fee")
	var fee map[string]any = nil
	if feeCost != nil {
		fee = map[string]any{
			"cost":     this.ParseNumber(feeCost),
			"currency": code,
		}
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          withdrawId,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"address":     nil,
		"addressTo":   this.SafeString(transaction, "to"),
		"addressFrom": this.SafeString(transaction, "from"),
		"tag":         nil,
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "status")),
		"updated":     this.SafeInteger(transaction, "confirmed_timestamp"),
		"comment":     nil,
		"internal":    false,
		"fee":         fee,
	})
}

