func (this *Polymarket) setLeverageBody(ch chan AsyncResult[map[string]any], leverage int64, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " setLeverage() requires a symbol argument"))
	}

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	var market map[string]any = this.Market(symbol)
	var marginMode *string = nil
	var paramsOmitted any = params
	marginMode, paramsOmitted = this.HandleMarginModeAndParams("setLeverage", paramsOmitted, "cross")
	var isCross bool = (marginMode == nil || *marginMode != "isolated")
	var instrumentId int64 = this.ParseToInt(market["id"])
	var leverageInt int64 = this.ParseToInt(leverage)
	var signable []any = []any{"updateLeverage", []any{instrumentId, leverageInt, isCross}}
	var bodyOp map[string]any = map[string]any{
		"type": "updateLeverage",
		"args": map[string]any{
			"cross": isCross,
			"iid":   instrumentId,
			"lev":   leverageInt,
		},
	}

	r1 := <-this.SignPerpsOpAsync(signable, bodyOp)
	if r1.Err != nil {
		panic(r1.Err)
	}
	signed := r1.Value

	r2 := <-this.TradePatchTradeLeverage(signed)
	if r2.Err != nil {
		panic(r2.Err)
	}
	response := r2.Value

	//
	//     { "status": "ok", "instrument_id": 1, "leverage": 10, "cross": true }
	//
	ch <- AsyncResult[map[string]any]{Value: response}
	return nil
}

