func (this *Polymarket) SignHash(hash any, privateKey any) any {
	var signature map[string]any = Ecdsa(Slice(hash, int64(-64), nil), Slice(privateKey, int64(-64), nil), secp256k1, nil)
	var r *string = SafeStringPtr(signature["r"])
	var sVal *string = SafeStringPtr(signature["s"])
	var v string = this.IntToBase16(this.Sum(27, signature["v"]))
	return "0x" + PadStart(r, 64, "0") + PadStart(sVal, 64, "0") + v
}
func (this *Polymarket) SignMessage(message any, privateKey any) any {
	return this.SignHash(this.HashMessage(message), privateKey)
}

/**
 * @method
 * @name polymarket#createProxyCredentials
 * @description provisions fresh trading session credentials - generates a proxy keypair, registers it with an EIP-712 CreateProxy message signed by the wallet key and caches the returned secret, the venue keeps the session valid for the requested lifetime
 * @see https://docs.polymarket.com/perps/authenticated-sessions
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} the session credentials, holding the proxy address, the proxy private key, the secret and the expiry timestamp
 */
func (this *Polymarket) CreateProxyCredentialsAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.createProxyCredentialsBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) createProxyCredentialsBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	// the session key derives from an ecdsa signature under the wallet
	// key over a timestamped nonce - unpredictable without the wallet
	// secret and unique per provisioning, the paradex stark-key idiom
	var nonceMessage string = "polymarket-perps-proxy:" + strconv.FormatInt(this.Milliseconds(), 10) + ":" + strconv.FormatInt(this.RandNumber(9), 10)
	var seedSignature any = this.SignMessage(nonceMessage, this.PrivateKey)
	var proxyPrivateKey any = this.Hash(this.Encode(seedSignature), keccak, "hex")
	var proxyAddress string = this.EthGetAddressFromPrivateKey(proxyPrivateKey)
	var owner string = this.EthGetAddressFromPrivateKey(this.PrivateKey)
	var ts int64 = this.Milliseconds()
	var lifetime *int64 = this.SafeInteger(this.Options, "proxyExpiry", 604800000)
	var expiry int64 = this.Sum(ts, lifetime).(int64)
	var salt int64 = this.RandNumber(9)
	var chainId *int64 = this.SafeInteger(this.Options, "chainId", 137)
	var domain map[string]any = map[string]any{
		"name":    "Polymarket",
		"version": "1",
		"chainId": chainId,
	}
	var messageTypes map[string]any = map[string]any{
		"CreateProxy": []any{map[string]any{
			"name": "addr",
			"type": "address",
		}, map[string]any{
			"name": "exp",
			"type": "uint64",
		}, map[string]any{
			"name": "salt",
			"type": "uint64",
		}, map[string]any{
			"name": "ts",
			"type": "uint64",
		}},
	}
	var message map[string]any = map[string]any{
		"addr": proxyAddress,
		"exp":  expiry,
		"salt": salt,
		"ts":   ts,
	}
	var encoded []uint8 = this.EthEncodeStructuredData(domain, messageTypes, message)
	var signature any = this.SignMessage(encoded, this.PrivateKey)
	var request map[string]any = map[string]any{
		"op": map[string]any{
			"type": "createProxy",
			"args": map[string]any{
				"expiry": expiry,
				"owner":  owner,
				"proxy":  proxyAddress,
			},
		},
		"salt": salt,
		"sig":  signature,
		"ts":   ts,
	}

	r := <-this.TradePostAccountProxy(this.Extend(request, params))
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value
	//
	//     { "secret": "..." }
	//
	var credentials map[string]any = map[string]any{
		"proxy":      proxyAddress,
		"privateKey": proxyPrivateKey,
		"secret":     this.SafeString(response, "secret"),
		"expires":    expiry,
	}
	this.Options["proxyCredentials"] = credentials

	ch <- AsyncResult[any]{Value: credentials}
	return nil
}

/**
 * @method
 * @ignore
 * @name polymarket#loadProxyCredentials
 * @description returns the cached trading session credentials, provisioning fresh ones when none are cached or the cached session is close to its expiry
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} the session credentials, holding the proxy address, the proxy private key, the secret and the expiry timestamp
 */
func (this *Polymarket) LoadProxyCredentialsAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.loadProxyCredentialsBody(ch, optionalArgs...)
	return ch
}
func (this *Polymarket) loadProxyCredentialsBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var credentials map[string]any = this.SafeDictMap(this.Options, "proxyCredentials")
	if credentials != nil {
		var expires *int64 = this.SafeInteger(credentials, "expires")
		var margin int64 = *this.SafeInteger(this.Options, "proxyRefreshMargin", 3600000)
		if expires == nil {

			ch <- AsyncResult[any]{Value: credentials}
			return nil
		}
		var refreshAfter int64 = *expires - margin
		if this.Milliseconds() < refreshAfter {

			ch <- AsyncResult[any]{Value: credentials}
			return nil
		}
	}

	r := <-this.CreateProxyCredentialsAsync(params)
	if r.Err != nil {
		panic(r.Err)
	}
	ch <- AsyncResult[any]{Value: r.Value}
	return nil
}

/**
 * @method
 * @ignore
 * @name polymarket#signPerpsOp
 * @description signs a trading operation with the session proxy key - the compact signable array is msgpack-encoded and keccak-hashed, the hash is signed inside an EIP-712 Op struct and the structured operation travels next to the signature
 * @param {any[]} signable the compact positional operation array, undefined entries already removed
 * @param {object} bodyOp the structured operation object transmitted to the venue
 * @returns {object} the signed request body with the op, sig, salt and ts fields
 */
func (this *Polymarket) SignPerpsOpAsync(signable any, bodyOp any, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.signPerpsOpBody(ch, signable, bodyOp, optionalArgs...)
	return ch
}
func (this *Polymarket) signPerpsOpBody(ch chan AsyncResult[any], signable any, bodyOp any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.LoadProxyCredentialsAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	credentials := r.Value
	var packed any = this.Packb(signable)
	var dataHash any = this.HashMessage(packed)
	var ts int64 = this.Milliseconds()
	var salt int64 = this.RandNumber(9)
	var chainId *int64 = this.SafeInteger(this.Options, "chainId", 137)
	var domain map[string]any = map[string]any{
		"name":    "Polymarket",
		"version": "1",
		"chainId": chainId,
	}
	var messageTypes map[string]any = map[string]any{
		"Op": []any{map[string]any{
			"name": "data",
			"type": "bytes32",
		}, map[string]any{
			"name": "salt",
			"type": "uint64",
		}, map[string]any{
			"name": "ts",
			"type": "uint64",
		}},
	}
	var message map[string]any = map[string]any{
		"data": dataHash,
		"salt": salt,
		"ts":   ts,
	}
	var encoded []uint8 = this.EthEncodeStructuredData(domain, messageTypes, message)
	var proxyPrivateKey *string = this.SafeString(credentials, "privateKey")
	var signature any = this.SignMessage(encoded, proxyPrivateKey)
	var envelope map[string]any = map[string]any{
		"op":   bodyOp,
		"sig":  signature,
		"salt": salt,
		"ts":   ts,
	}
	// the optional command expiry travels next to the signature and is
	// not part of the signed payload
	var exp *int64 = this.SafeInteger(params, "exp")
	if exp != nil {
		envelope["exp"] = exp
	}

	ch <- AsyncResult[any]{Value: envelope}
	return nil
}

/**
 * @method
 * @ignore
 * @name polymarket#compactSignable
 * @description removes undefined entries from a positional signable array, later entries shift left exactly like the official sdk does before hashing
 * @param {any[]} row the positional array to compact
 * @returns {any[]} the compacted array
 */
func (this *Polymarket) CompactSignable(row []any) any {
	var result []any = []any{}
	for i := 0; i < len(row); i++ {
		if !IsEqual(DerefScalar(row[i]), nil) {
			result = append(result, DerefScalar(row[i]))
		}
	}
	return result
}
func (this *Polymarket) PriceToPrecision(symbol any, price any) *string {
	if IsEqual(price, nil) {
		return SafeStringPtr(nil)
	}
	// the venue caps prices at five significant figures on top of the
	// per-instrument decimals, deliberately for any magnitude - a six
	// digit integer price coarsens to an effective step of ten
	var market map[string]any = this.Market(symbol)
	var precision map[string]any = SafeMapTyped(market, "precision")
	var significant string = this.DecimalToPrecision(price, ROUND, 5, SIGNIFICANT_DIGITS)
	var result string = this.DecimalToPrecision(significant, ROUND, precision["price"], TICK_SIZE)
	if result == "0" {
		panic(InvalidOrder(Add(this.Id+" price of "+market["symbol"].(string)+" must be greater than minimum price precision of ", this.NumberToString(precision["price"]))))
	}
	return SafeStringPtr(result)
}
func (this *Polymarket) AmountToPrecision(symbol any, amount any) *string {
	if IsEqual(amount, nil) {
		return SafeStringPtr(nil)
	}
	// quantities carry the same five significant figures cap
	var market map[string]any = this.Market(symbol)
	var precision map[string]any = SafeMapTyped(market, "precision")
	var significant string = this.DecimalToPrecision(amount, TRUNCATE, 5, SIGNIFICANT_DIGITS)
	var result string = this.DecimalToPrecision(significant, TRUNCATE, precision["amount"], TICK_SIZE)
	if result == "0" {
		panic(InvalidOrder(Add(this.Id+" amount of "+market["symbol"].(string)+" must be greater than minimum amount precision of ", this.NumberToString(precision["amount"]))))
	}
	return SafeStringPtr(result)
}
func (this *Polymarket) CalculateRateLimiterCost(api any, method string, path string, params any, optionalArgs ...any) any {
	var config map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = config
	if path == "account/orders" {
		return func() int {
			if InOp(params, "order_id") {
				return 1
			}
			return 10
		}()
	}
	if path == "account/open-orders" {
		return func() int {
			if InOp(params, "instrument_id") {
				return 1
			}
			return 20
		}()
	}
	if (path == "trade/orders") || (path == "trade/orders-coid") {
		var op map[string]any = SafeMapTyped(params, "op")
		var args []any = SafeListTyped(op, "args")
		return this.Sum(1, this.ParseToInt(float64(len(args))/20))
	}
	if path == "info/book" {
		var depth int64 = *this.SafeInteger(params, "depth", 100)
		if depth <= 10 {
			return 2
		} else if depth <= 100 {
			return 5
		} else if depth <= 500 {
			return 10
		}
		return 20
	}
	return this.SafeValue(config, "cost", 1)
}
func (this *Polymarket) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var apiType string = api[0]
	var baseUrl *string = this.SafeString(this.Urls["api"], apiType, "")
	var implodedPath string = this.ImplodeParams(path, params)
	var url string = *baseUrl + "/" + implodedPath
	var query any = this.Omit(params, this.ExtractParams(path))
	var headersResolved map[string]any = map[string]any{
		"Accept": "application/json",
	}
	var bodyResolved *string = nil
	if apiType == "trade" {
		// the params hold the signed operation envelope assembled by the
		// calling method, the signature authenticates so no headers apply
		jsonText := this.Json(query)
		bodyResolved = &jsonText
		headersResolved["Content-Type"] = "application/json"
	} else {
		if method == "GET" {
			var keys []string = ObjectKeys(query)
			var keysLength int = len(keys)
			if keysLength > 0 {
				url = *baseUrl + "/" + implodedPath + "?" + this.Urlencode(query)
			}
		}
		if apiType == "private" {
			var credentials map[string]any = SafeMapTyped(this.Options, "proxyCredentials")
			headersResolved["POLYMARKET-PROXY"] = this.SafeString(credentials, "proxy")
			headersResolved["POLYMARKET-SECRET"] = this.SafeString(credentials, "secret")
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResolved,
		"headers": headersResolved,
	}
}
func (this *Polymarket) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	//
	//     {
	//         "status": "err",
	//         "error": "invalid query parameters: missing field `interval`",
	//         "arts": 1788524547131,
	//         "ts": 1788524547131,
	//         "ref": "g-164de39df348d7"
	//     }
	//
	var source any = response
	if IsArray(response) && (code >= 400) {
		// request-level failures of the batch trade endpoints arrive
		// wrapped into a single-element array of the same error shape
		source = this.SafeDict(response, 0, map[string]any{})
	}
	var status *string = this.SafeString(source, "status")
	var error *string = this.SafeString(source, "error")
	if (status != nil && *status == "err") || (error != nil) {
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], error, feedback)
		if code == 400 {
			panic(BadRequest(feedback))
		}
		// an unmapped error on a 4xx or 5xx response falls through so the
		// http status fallback can apply a retryable classification, while
		// covering statuses the base table does not know
		var codeAsString string = strconv.FormatInt(code, 10)
		if _, ok := this.HttpExceptions[codeAsString]; (code < 400) || !ok {
			panic(ExchangeError(feedback))
		}
	}
	return nil
}

func NewPolymarket(userConfig map[string]any) *Polymarket {
	p := newPolymarket()
	p.Init(userConfig)
	return p
}

func (this *Polymarket) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

